INSERT INTO feature VALUES('sibling-imports','modules','Importing a sibling source','imports','implemented','ordinary',NULL,'An import by path brings a sibling source''s declarations into the importer, which is checked against them; since the fold (#436, closed by #623) every corpus subject is one base source its siblings import, every lemma written once, the dispatcher judging the import-connected component once (#592), and a gate refuses a subject that declares a name twice.','surface-lowering surface-dispatcher','corpus/model/identity/circle-base.gandr corpus/model/data/data-base.gandr corpus/model/universe/ corpus/model/control/ corpus/model/circuit/ corpus/pathological/modules/import-unresolved.gandr corpus/pathological/modules/import-cycle-a.gandr corpus/pathological/modules/import-shadows.gandr corpus/model/higher-cells/magma-base.gandr corpus/model/sessions/seat-base.gandr','corpus/model/identity/circle-base.gandr',NULL);
